using namespace std;
using namespace __gnu_pbds;

auto get_random_address = [] { char *p = new char; delete p; return (uint64_t) p; };

struct HashSplitter {
    static uint64_t splitmix64(uint64_t x) {
        x += 0x9e3779b97f4a7c15ULL;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
        x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
        return x ^ (x >> 31);
    }

    uint64_t operator()(uint64_t x) const {
        static const uint64_t seed = splitmix64(chrono::steady_clock::now().time_since_epoch().count() * (get_random_address() | 1));
        return splitmix64(x ^ seed);
    }
};

const int MOD_CONST = 1e9 + 7;

struct Modular {
    int value;

    Modular(long long v = 0) {
        if (v < 0) v = v % MOD_CONST + MOD_CONST;
        if (v >= MOD_CONST) v %= MOD_CONST;
        value = v;
    }

    static int extended_gcd(int a, int m, int &x, int &y) {
        if (m == 0) {
            x = 1; y = 0;
            return a;
        }
        int g = extended_gcd(m, a % m, y, x);
        y -= (a / m) * x;
        return g;
    }

    static int modular_inverse(int a, int m = MOD_CONST) {
        int x, y;
        extended_gcd(a, m, x, y);
        return (x % m + m) % m;
    }

    explicit operator int() const { return value; }

    Modular& operator+=(const Modular &other) {
        value += other.value;
        if (value >= MOD_CONST) value -= MOD_CONST;
        return *this;
    }

    Modular& operator-=(const Modular &other) {
        value -= other.value;
        if (value < 0) value += MOD_CONST;
        return *this;
    }

    Modular& operator*=(const Modular &other) {
        value = (uint64_t(value) * other.value) % MOD_CONST;
        return *this;
    }

    Modular& operator/=(const Modular &other) {
        return *this *= Modular(modular_inverse(other.value));
    }

    friend Modular operator+(const Modular &a, const Modular &b) { return Modular(a) += b; }
    friend Modular operator-(const Modular &a, const Modular &b) { return Modular(a) -= b; }
    friend Modular operator*(const Modular &a, const Modular &b) { return Modular(a) *= b; }
    friend Modular operator/(const Modular &a, const Modular &b) { return Modular(a) /= b; }

    Modular pow(long long p) const {
        assert(p >= 0);
        Modular res = 1, base = *this;
        while (p > 0) {
            if (p & 1) res *= base;
            base *= base;
            p >>= 1;
        }
        return res;
    }
};

int main() {
    int N;
    cin >> N;
    vector<vector<Modular>> prob(N, vector<Modular>(N));
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j) {
            int p;
            cin >> p;
            prob[i][j] = Modular(p) / Modular(100);
        }

    vector<vector<int>> masks_by_count(N + 1);
    vector<int> lookup_mask(1 << N, -1);
    for (int mask = 0; mask < (1 << N); ++mask) {
        int c = __builtin_popcount(mask);
        lookup_mask[mask] = (int)masks_by_count[c].size();
        masks_by_count[c].push_back(mask);
    }

    gp_hash_table<long long, Modular, HashSplitter> possible_states;
    possible_states[1LL << lookup_mask[0]] = Modular(1);

    for (int left = 0; left < N; ++left) {
        gp_hash_table<long long, Modular, HashSplitter> new_states;
        vector<Modular> product_mask(1 << N, Modular(1));
        for (int current_mask = 0; current_mask < (1 << N); ++current_mask) {
            for (int col = 0; col < N; ++col) {
                Modular p = prob[left][col];
                if (current_mask & (1 << col))
                    product_mask[current_mask] *= p;
                else
                    product_mask[current_mask] *= (Modular(1) - p);
            }
        }

        vector<long long> new_bits(N, 0);
        vector<Modular> new_possible(1 << N, Modular(0));

        for (auto &state : possible_states) {
            long long mask_state = state.first;
            Modular prob_state = state.second;
            fill(new_bits.begin(), new_bits.end(), 0);
            for (int m : masks_by_count[left]) {
                if ((mask_state >> lookup_mask[m]) & 1) {
                    for (int i = 0; i < N; ++i) {
                        if (((m >> i) & 1) == 0) {
                            new_bits[i] |= 1LL << lookup_mask[m | (1 << i)];
                        }
                    }
                }
            }
            fill(new_possible.begin(), new_possible.end(), Modular(0));
            for (int current_mask = 1; current_mask < (1 << N); ++current_mask) {
                int ctz = __builtin_ctz(current_mask);
                new_possible[current_mask] = new_possible[current_mask & (current_mask - 1)] | new_bits[ctz];
                long long combined_mask = new_possible[current_mask];
                new_states[combined_mask] += prob_state * product_mask[current_mask];
            }
        }
        possible_states = move(new_states);
    }

    Modular answer = 0;
    for (auto &state : possible_states) {
        if (((state.first >> lookup_mask[(1 << N) - 1]) & 1) != 0)
