import java.util.*;
import java.io.*;

public class Main {
    static final int MOD_CONST = 1000000007;

    static class Modular {
        int value;

        Modular(long v) {
            v %= MOD_CONST;
            if (v < 0) v += MOD_CONST;
            this.value = (int) v;
        }

        static int extendedGCD(int a, int m, int[] xy) {
            if (m == 0) {
                xy[0] = 1;
                xy[1] = 0;
                return a;
            }
            int[] yx = new int[2];
            int g = extendedGCD(m, a % m, yx);
            int y = yx[0], x = yx[1];
            xy[0] = y;
            xy[1] = x - (a / m) * y;
            return g;
        }

        static int modularInverse(int a) {
            int[] xy = new int[2];
            extendedGCD(a, MOD_CONST, xy);
            int x = xy[0];
            return (x % MOD_CONST + MOD_CONST) % MOD_CONST;
        }

        Modular add(Modular other) {
            int res = this.value + other.value;
            if (res >= MOD_CONST) res -= MOD_CONST;
            return new Modular(res);
        }

        Modular subtract(Modular other) {
            int res = this.value - other.value;
            if (res < 0) res += MOD_CONST;
            return new Modular(res);
        }

        Modular multiply(Modular other) {
            long res = (long) this.value * other.value % MOD_CONST;
            return new Modular(res);
        }

        Modular divide(Modular other) {
            return this.multiply(new Modular(modularInverse(other.value)));
        }

        Modular pow(long p) {
            assert p >= 0;
            Modular res = new Modular(1);
            Modular base = this;
            while (p > 0) {
                if ((p & 1) == 1) res = res.multiply(base);
                base = base.multiply(base);
                p >>= 1;
            }
            return res;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine());
        Modular[][] prob = new Modular[N][N];
        for (int i = 0; i < N; i++) {
            String[] parts = br.readLine().split(" ");
            for (int j = 0; j < N; j++) {
                int p = Integer.parseInt(parts[j]);
                prob[i][j] = new Modular(p).divide(new Modular(100));
            }
        }

        List<List<Integer>> masksByCount = new ArrayList<>();
        for (int i = 0; i <= N; i++) {
            masksByCount.add(new ArrayList<>());
        }
        int[] lookupMask = new int[1 << N];
        Arrays.fill(lookupMask, -1);
        for (int mask = 0; mask < (1 << N); mask++) {
            int c = Integer.bitCount(mask);
            lookupMask[mask] = masksByCount.get(c).size();
            masksByCount.get(c).add(mask);
        }

        Map<Long, Modular> possibleStates = new HashMap<>();
        long initialMask = 1L << lookupMask[0];
        possibleStates.put(initialMask, new Modular(1));

        for (int left = 0; left < N; left++) {
            Map<Long, Modular> newStates = new HashMap<>();
            Modular[] productMask = new Modular[1 << N];
            Arrays.fill(productMask, new Modular(1));
            for (int current_mask = 0; current_mask < (1 << N); current_mask++) {
                Modular prod = new Modular(1);
                for (int col = 0; col < N; col++) {
                    Modular p = prob[left][col];
                    if (((current_mask >> col) & 1) != 0) {
                        prod = prod.multiply(p);
                    } else {
                        prod = prod.multiply(new Modular(1).subtract(p));
                    }
                }
                productMask[current_mask] = prod;
            }

            long[] newBits = new long[N];
            Arrays.fill(newBits, 0L);
            Map<Long, Modular> newPossible = new HashMap<>();
            for (Map.Entry<Long, Modular> state : possibleStates.entrySet()) {
                long maskState = state.getKey();
                Modular probState = state.getValue();
                Arrays.fill(newBits, 0L);
                for (int m : masksByCount.get(left)) {
                    if (((maskState >> lookupMask[m]) & 1) != 0) {
                        for (int i = 0; i < N; i++) {
                            if (((m >> i) & 1) == 0) {
                                long newMaskBit = 1L << lookupMask[m | (1 << i)];
                                newBits[i] |= newMaskBit;
                            }
                        }
                    }
                }
                for (int current_mask = 1; current_mask < (1 << N); current_mask++) {
                    int ctz = Integer.numberOfTrailingZeros(current_mask);
                    long prevMask = current_mask & (current_mask - 1);
                    long combinedMask = newBits[ctz] | (prevMask != 0 ? newBits[Integer.numberOfTrailingZeros(prevMask)] : 0);
                    Modular val = probState.multiply(productMask[current_mask]);
                    long existing = newStates.getOrDefault(combinedMask, new Modular(0)).value;
                    newStates.put(combinedMask, new Modular(existing).add(val));
                }
            }
            possibleStates = newStates;
        }

        Modular answer = new Modular(0);
        for (Map.Entry<Long, Modular> state : possibleStates.entrySet()) {
            long mask = state.getKey();
            if (((mask >> lookupMask[(1 << N) - 1]) & 1) != 0) {
                answer = answer.add(state.getValue());
            }
        }
        System.out.println(answer.value);
    }
}
